// fakeCloudflare serves the Cloudflare API calls the edge makes and records
// every write.
type fakeCloudflare struct {
	t                 *testing.T
	ranges            []string
	ruleset           *fakeRuleset
	aop               bool
	certificates      []originPullCertificate
	hostnameOverrides map[string]any
	aopErrorPath      string
