// ParsePlan reads a regional plan's public API from its JSON.
func ParsePlan(wire []byte) (Desired, error) {
	var p planFile
	if err := json.Unmarshal(wire, &p); err != nil {
		return Desired{}, fmt.Errorf("plan: %w", err)
	}
