origin_steps.text:
// originSteps plans the load balancer NSG's sync to Cloudflare's ranges.
func (p Provisioner) originSteps(ctx context.Context, d Desired, cloudflare Cloudflare) ([]step, error) {
	if d.Network == "" || d.VCN == "" {
		return nil, errors.New("plan resource_ids.network_compartment and vcn are required")
	}
	ranges, err := cloudflare.OriginIPs(ctx)
	if err != nil {
		return nil, err
	}
	nsg, err := p.nsg(ctx, d)
	if err != nil {
		return nil, err
	}
	return p.syncRules(ctx, nsg, "Cloudflare to the public API", OriginRules(ranges), true)
}

provision.text:
// Provision creates the edge's missing network and load balancer in
// dependency order. Every resource is found by its static name first, so a
// rerun resumes. The origin certificate must already be in Vault.
func (p Provisioner) Provision(ctx context.Context, d Desired, cloudflare Cloudflare, members, cell string) (map[string]any, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := d.OriginPull.Validate(); err != nil {
		return nil, err
	}
	for key, value := range map[string]string{"network_compartment": d.Network, "control_compartment": d.Control, "vcn": d.VCN,
		"network_security_group": d.ControllerNSG, "workload_network_security_group": d.WorkloadNSG, "vault": d.Vault} {
		if value == "" {
			return nil, fmt.Errorf("plan resource_ids.%s is required", key)
		}
	}
	if err := validCA(members); err != nil {
		return nil, err
	}
	if d.OrchHost != "" {
		if err := validCA(cell); err != nil {
			return nil, err
		}
	}
	ranges, err := cloudflare.OriginIPs(ctx)
	if err != nil {
		return nil, err
	}
	balancer, err := p.balancer(ctx, d)
	if err != nil {
		return nil, err
	}
	var origin, key string
	if balancer == nil {
		secret, err := p.secret(ctx, d)
		if err != nil {
			return nil, err
		}
		if secret == nil {
			return nil, fmt.Errorf("vault secret %s does not exist; run public-api cert --apply first", d.Names.Secret)
		}
		if origin, key, err = p.originBundle(ctx, secret, d.hostNames()); err != nil {
			return nil, err
		}
	}
	edge, err := p.network(ctx, d, true)
	if err != nil {
		return nil, err
	}
	if balancer != nil {
		if err := d.checkAttachments(balancer, edge.subnet, edge.nsg); err != nil {
			return nil, err
		}
	}
	for _, sync := range []struct {
		id, description string
		rules           []Rule
		remove          bool
	}{
		{edge.nsg, "Cloudflare to the public API", OriginRules(ranges), true},
		{d.WorkloadNSG, "TerraBase HTTPS from the public API load balancer", []Rule{{d.PublicCIDR, d.ClientPort}}, false},
		{d.ControllerNSG, "ts-auth from the public API load balancer", []Rule{{d.PublicCIDR, AuthPort}}, false},
	} {
		if sync.id == d.ControllerNSG && d.OrchHost != "" {
			sync.rules = append(sync.rules, Rule{d.PublicCIDR, OrchPort})
		}
		steps, err := p.syncRules(ctx, sync.id, sync.description, sync.rules, sync.remove)
		if err != nil {
			return nil, err
		}
		if err := run(ctx, steps, true, io.Discard); err != nil {
			return nil, err
		}
	}
	if balancer == nil {
		args := []string{"lb", "load-balancer", "create", "--compartment-id", d.Network, "--display-name", d.Names.LB,
			"--shape-name", "flexible", "--subnet-ids", command.JSON([]string{edge.subnet}), "--is-private", "false",
			"--network-security-group-ids", command.JSON([]string{edge.nsg})}
		config := d.loadBalancer(origin, key, members, cell)
		for _, flag := range []string{"shape-details", "certificates", "hostnames", "backend-sets", "listeners", "rule-sets"} {
			args = append(args, "--"+flag, config[flag])
		}
		if _, err := p.Client.Call(ctx, args...); err != nil {
			return nil, err
		}
	}
	balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) },
		func(r map[string]any) bool { return r["lifecycle-state"] == "ACTIVE" })
	if err != nil {
		return nil, err
	}
	if err := d.checkAttachments(balancer, edge.subnet, edge.nsg); err != nil {
		return nil, err
	}
	// Renaming a host before its certificate names it would serve a mismatch.
	served, _ := field(balancer, "certificates", servedCertificate(balancer), "public-certificate").(string)
	if _, err := checkOriginCertificate(served, d.hostNames(), time.Now()); err != nil {
		return nil, fmt.Errorf("load balancer %s origin certificate: %w; run public-api cert --apply first", d.Names.LB, err)
	}
	if balancer, err = p.converge(ctx, d, balancer); err != nil {
		return nil, err
	}
	if balancer, err = p.routeManagement(ctx, d, balancer); err != nil {
		return nil, err
	}
	if err := d.checkAttachments(balancer, edge.subnet, edge.nsg); err != nil {
		return nil, err
	}
	// Certificates and listeners are fixed at creation; report drift apply
	// cannot repair rather than claim success.
	if !sameCA(balancer, memberCA, members) {
		return nil, fmt.Errorf("load balancer %s trusts a different member CA than --member-ca; add the new CA as another certificate bundle and point backend set terrabase at it", d.Names.LB)
	}
	if d.OrchHost != "" && !sameCA(balancer, cellCA, cell) {
		return nil, fmt.Errorf("load balancer %s trusts a different cell CA than --cell-ca", d.Names.LB)
	}
	if err := p.validateOrigin(ctx, d, balancer, ranges); err != nil {
		return nil, err
	}
	public, err := publicIP(balancer)
	if err != nil {
		return nil, err
	}
	return map[string]any{"internet_gateway": edge.gateway, "public_route_table": edge.routes, "public_security_list": edge.security,
		"public_subnet": edge.subnet, "network_load_balancer": balancer["id"], "load_balancer_nsg": edge.nsg, "public_ip": public.String()}, nil
}

live_ownership.text:
// liveBackends are a live backend set's backends as sorted ip:port.
func liveBackends(balancer map[string]any, set string) []string {
	sets, _ := balancer["backend-sets"].(map[string]any)
	live, _ := sets[set].(map[string]any)
	rows, _ := command.Rows(live["backends"])
	var out []string
	for _, b := range rows {
		out = append(out, fmt.Sprintf("%v:%v", b["ip-address"], b["port"]))
	}
	slices.Sort(out)
	return out
}

// controllerOwned reports whether the controller's oci_reconcile.public_lb
// owns the terrabase backends: only a plan that names orchestrator_owner
// stamps the ownership the controller needs. Without it apply keeps
// converging the set to the seed, as before TS-571.
func (d Desired) controllerOwned() bool { return d.Owner != "" }

// ownership is the controller's freeform ownership for Owned.
func (d Desired) ownership() ociresource.Ownership {
	return ociresource.Ownership{Mode: ociresource.TagModeFreeform, Owner: d.Owner}
}

// freeformTags reads a CLI-shaped load balancer's freeform tags.
func freeformTags(balancer map[string]any) map[string]string {
	tags := map[string]string{}
	live, _ := balancer["freeform-tags"].(map[string]any)
	for name, value := range live {
		tags[name] = fmt.Sprint(value)
	}
	return tags
}

// ownershipTags returns the load balancer's freeform tags with the
// controller's ownership of the terrabase backend set added, or nil when
// they already carry it. A load balancer carrying any other or partial
// ownership claim is refused.
func (d Desired) ownershipTags(balancer map[string]any) (map[string]string, error) {
	tags := freeformTags(balancer)
	if d.ownership().Owns(d.Owned, ociresource.Tags{Freeform: tags}) {
		return nil, nil
	}
	if d.ownership().Claimed(ociresource.Tags{Freeform: tags}) {
		return nil, fmt.Errorf("load balancer %s carries another ts-orchestrator ownership than %s; resolve it by hand", d.Names.LB, d.Owned)
	}
	maps.Copy(tags, d.ownership().Stamp(d.Owned, 0, "").Freeform)
	return tags, nil
}

converge.text:
// converge brings an existing load balancer's bandwidth, hostnames and
// ts-auth backends to the plan, and stamps the controller's ownership of the
// terrabase backend set when the plan names its owner. The terrabase backends belong to the
// controller (oci_reconcile.public_lb), which drains seats during releases;
// rewriting them here would undo that.
func (p Provisioner) converge(ctx context.Context, d Desired, balancer map[string]any) (map[string]any, error) {
	id, err := command.ID(balancer)
	if err != nil {
		return nil, err
	}
	// Ownership comes first: a load balancer another owner claims is refused
	// before anything changes, and one the controller owns is never handed
	// back to an ownerless plan, which would converge its drained seats.
	if d.Owner == "" && d.ownership().Claimed(ociresource.Tags{Freeform: freeformTags(balancer)}) {
		return nil, fmt.Errorf("load balancer %s carries ts-orchestrator ownership; name orchestrator_owner in the plan", d.Names.LB)
	}
	if d.Owner != "" {
		tags, err := d.ownershipTags(balancer)
		if err != nil {
			return nil, err
		}
		if tags != nil {
			if _, err := p.Client.Call(ctx, "lb", "load-balancer", "update", "--load-balancer-id", id, "--freeform-tags", command.JSON(tags)); err != nil {
				return nil, err
			}
			if balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
				owned, err := d.ownershipTags(r)
				return r["lifecycle-state"] == "ACTIVE" && owned == nil && err == nil
			}); err != nil {
				return nil, err
			}
		}
	}
	bandwidth := func(r map[string]any) bool {
		return same(field(r, "shape-details", "minimum-bandwidth-in-mbps"), d.MinMbps) && same(field(r, "shape-details", "maximum-bandwidth-in-mbps"), d.MaxMbps)
	}
	if !bandwidth(balancer) {
		if _, err := p.Client.Call(ctx, "lb", "load-balancer", "update-shape", "--load-balancer-id", id, "--shape-name", "flexible",
			"--shape-details", command.JSON(map[string]any{"minimumBandwidthInMbps": d.MinMbps, "maximumBandwidthInMbps": d.MaxMbps})); err != nil {
			return nil, err
		}
		if balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
			return r["lifecycle-state"] == "ACTIVE" && bandwidth(r)
		}); err != nil {
			return nil, err
		}
	}
	for _, h := range d.hosts() {
		name, host := h.set, h.name
		if field(balancer, "hostnames", name, "hostname") == host {
			continue
		}
		if _, err := p.Client.Call(ctx, "lb", "hostname", "update", "--load-balancer-id", id, "--name", name, "--hostname", host); err != nil {
			return nil, err
		}
		if balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
			return r["lifecycle-state"] == "ACTIVE" && field(r, "hostnames", name, "hostname") == host
		}); err != nil {
			return nil, err
		}
	}
	for name, set := range d.backendSets() {
		if (name == "terrabase" || name == primarySet) && d.controllerOwned() {
			continue
		}
		var want []string
		for _, b := range set["backends"].([]any) {
			want = append(want, fmt.Sprintf("%v:%v", b.(map[string]any)["ipAddress"], b.(map[string]any)["port"]))
		}
		slices.Sort(want)
		if slices.Equal(liveBackends(balancer, name), want) {
			continue
		}
		if _, err := p.Client.Call(ctx, "lb", "backend-set", "update", "--load-balancer-id", id, "--backend-set-name", name, "--details", command.JSON(set)); err != nil {
			return nil, err
		}
		if balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
			return r["lifecycle-state"] == "ACTIVE" && slices.Equal(liveBackends(r, name), want)
		}); err != nil {
			return nil, err
		}
	}
	return balancer, nil
}

route_management.text:
// routeManagement adds the managementRoutes routing policy and points the
// terrabase listener at it.
func (p Provisioner) routeManagement(ctx context.Context, d Desired, balancer map[string]any) (map[string]any, error) {
	id, err := command.ID(balancer)
	if err != nil {
		return nil, err
	}
	reload := func(ready func(map[string]any) bool) (err error) {
		balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
			return r["lifecycle-state"] == "ACTIVE" && ready(r)
		})
		return err
	}
	if field(balancer, "routing-policies", managementRoutes) == nil {
		if _, err := p.Client.Call(ctx, "lb", "routing-policy", "create", "--load-balancer-id", id, "--name", managementRoutes,
			"--condition-language-version", "V1", "--rules", command.JSON(managementRules)); err != nil {
			return nil, err
		}
		if err := reload(func(r map[string]any) bool { return field(r, "routing-policies", managementRoutes) != nil }); err != nil {
			return nil, err
		}
	}
	if field(balancer, "listeners", "terrabase", "routing-policy-name") != managementRoutes {
		if _, err := p.Client.Call(ctx, "lb", "listener", "update", "--load-balancer-id", id, "--listener-name", "terrabase",
			"--details", command.JSON(d.httpsListener("terrabase", servedCertificate(balancer)))); err != nil {
			return nil, err
		}
		if err := reload(func(r map[string]any) bool {
			return field(r, "listeners", "terrabase", "routing-policy-name") == managementRoutes
		}); err != nil {
			return nil, err
		}
	}
	return balancer, nil
}

dns.text:
// publicIP is a load balancer's one public address.
func publicIP(balancer map[string]any) (netip.Addr, error) {
	addresses, err := command.Rows(balancer["ip-addresses"])
	if err != nil {
		return netip.Addr{}, err
	}
	var public []netip.Addr
	for _, a := range addresses {
		if ip, err := netip.ParseAddr(fmt.Sprint(a["ip-address"])); a["is-public"] == true && err == nil {
			public = append(public, ip)
		}
	}
	if len(public) != 1 {
		return netip.Addr{}, fmt.Errorf("load balancer %v has %d public addresses, want 1", balancer["display-name"], len(public))
	}
	return public[0], nil
}

// RunDNS validates the origin without OCI writes before planning Cloudflare
// changes, including on a dry run.
func (p Provisioner) RunDNS(ctx context.Context, d Desired, cloudflare Cloudflare, apply bool, out io.Writer) error {
	if d.Network == "" || d.VCN == "" {
		return errors.New("plan resource_ids.network_compartment and vcn are required")
	}
	balancer, err := p.balancer(ctx, d)
	if err != nil {
		return err
	}
	if balancer == nil || balancer["lifecycle-state"] != "ACTIVE" {
		return fmt.Errorf("load balancer %s is not ACTIVE; run public-api apply first", d.Names.LB)
	}
	ranges, err := cloudflare.OriginIPs(ctx)
	if err != nil {
		return err
	}
	if err := p.validateOrigin(ctx, d, balancer, ranges); err != nil {
		return err
	}
	address, err := publicIP(balancer)
	if err != nil {
		return err
	}
	steps, err := cloudflare.edgeSteps(ctx, d.hostNames(), address, d.Cell, d.OriginPull)
	if err != nil {
		return err
	}
	return run(ctx, steps, apply, out)
}

cert_steps.text:
// certSteps plans the load balancer's origin certificate: a Cloudflare
// Origin CA certificate whose private key lives only in the cell's Vault
// secret and on the load balancer.
func (p Provisioner) certSteps(ctx context.Context, d Desired, cloudflare Cloudflare) ([]step, error) {
	if err := d.OriginPull.Validate(); err != nil {
		return nil, err
	}
	for key, value := range map[string]string{"control_compartment": d.Control, "network_compartment": d.Network, "vault": d.Vault, "key": d.Key} {
		if value == "" {
			return nil, fmt.Errorf("plan resource_ids.%s is required", key)
		}
	}
	secret, err := p.secret(ctx, d)
	if err != nil {
		return nil, err
	}
	balancer, err := p.balancer(ctx, d)
	if err != nil {
		return nil, err
	}
	hostnames := d.hostNames()
	var origin, key string
	rotate := false
	if secret != nil {
		if origin, key, err = p.originBundle(ctx, secret, nil); err != nil {
			return nil, err
		}
		// A bundle missing a planned name, or within a year of expiry, gets a
		// new version; earlier versions stay in the Vault.
		rotate = checkOrigin(origin, key, hostnames, time.Now().AddDate(1, 0, 0)) != nil
	}
	issue := func(ctx context.Context, store func(string) error) error {
		certificate, private, id, err := issueOrigin(ctx, cloudflare, hostnames)
		if err != nil {
			return err
		}
		if err := store(certificate + private); err != nil {
			return fmt.Errorf("%w; revoke unused Origin CA certificate %s in Cloudflare", err, id)
		}
		origin, key = certificate, private
		return nil
	}
	what := fmt.Sprintf("a Cloudflare Origin CA certificate for %s (RSA 2048, %d days)", strings.Join(hostnames, " and "), originValidityDays)
	var steps []step
	switch {
	case secret == nil:
		steps = append(steps, step{fmt.Sprintf("create %s into vault secret %s", what, d.Names.Secret), func(ctx context.Context) error {
			return issue(ctx, func(bundle string) error { return p.storeSecret(ctx, d, bundle) })
		}})
	case rotate:
		steps = append(steps, step{fmt.Sprintf("add %s as a new version of vault secret %s", what, d.Names.Secret), func(ctx context.Context) error {
			return issue(ctx, func(bundle string) error { return p.rotateSecret(ctx, d, secret, bundle) })
		}})
	}
	if balancer != nil {
		served, _ := field(balancer, "certificates", servedCertificate(balancer), "public-certificate").(string)
		if secret == nil || rotate || !sameCertificate(served, origin) {
			id := fmt.Sprint(balancer["id"])
			steps = append(steps, step{fmt.Sprintf("install the origin certificate on %s and serve it on every HTTPS listener", d.Names.LB),
				func(ctx context.Context) error { return p.serveOrigin(ctx, d, id, origin, key) }})
		}
	}
	return steps, nil
}

serve_cert.text:
// serveOrigin installs an origin certificate under a name derived from its
// content, since a load balancer certificate cannot be replaced in place, and
// points every HTTPS listener at it. The certificate it replaces stays
// installed until an operator deletes it.
func (p Provisioner) serveOrigin(ctx context.Context, d Desired, id, origin, key string) error {
	name := certificateName(origin)
	balancer, err := p.balancer(ctx, d)
	if err != nil {
		return err
	}
	reload := func(ready func(map[string]any) bool) error {
		balancer, err = p.await(ctx, d.Names.LB, func() (map[string]any, error) { return p.balancer(ctx, d) }, func(r map[string]any) bool {
			return r["lifecycle-state"] == "ACTIVE" && ready(r)
		})
		return err
	}
	if field(balancer, "certificates", name) == nil {
		if _, err := p.Client.Call(ctx, "lb", "certificate", "create", "--load-balancer-id", id, "--certificate", command.JSON(map[string]string{
			"certificateName": name, "publicCertificate": origin, "privateKey": key, "caCertificate": d.OriginPull.CACertificate})); err != nil {
			return err
		}
		if err := reload(func(r map[string]any) bool { return field(r, "certificates", name) != nil }); err != nil {
			return err
		}
	}
	for _, h := range d.hosts() {
		listener := h.set
		if field(balancer, "listeners", listener, "ssl-configuration", "certificate-name") == name {
			continue
		}
		if _, err := p.Client.Call(ctx, "lb", "listener", "update", "--load-balancer-id", id, "--listener-name", listener,
			"--details", command.JSON(d.httpsListener(listener, name))); err != nil {
			return err
		}
		if err := reload(func(r map[string]any) bool {
			return field(r, "listeners", listener, "ssl-configuration", "certificate-name") == name
		}); err != nil {
			return err
		}
	}
	return nil
}

cert_names.text:
// servedCertificate is the certificate the TerraBase HTTPS listener serves.
func servedCertificate(lb map[string]any) string {
	name, _ := field(lb, "listeners", "terrabase", "ssl-configuration", "certificate-name").(string)
	return name
}

// certificateName names an origin certificate installed after the first by
// its content, so a rerun finds it.
func certificateName(certificatePEM string) string {
	block, _ := pem.Decode([]byte(certificatePEM))
	if block == nil {
		return originCertificate
	}
	sum := sha256.Sum256(block.Bytes)
	return originCertificate + "-" + hex.EncodeToString(sum[:6])
}

// sameCertificate compares two PEM certificates by DER.
func sameCertificate(a, b string) bool {
	x, _ := pem.Decode([]byte(a))
	y, _ := pem.Decode([]byte(b))
	return x != nil && y != nil && bytes.Equal(x.Bytes, y.Bytes)
}

issue_cert.text:
// issueOrigin creates a key and has Cloudflare's Origin CA certify it.
func issueOrigin(ctx context.Context, cloudflare Cloudflare, hostnames []string) (certificate, key, id string, err error) {
	private, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", "", "", err
	}
	request, err := x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{Subject: pkix.Name{CommonName: hostnames[0]}, DNSNames: hostnames}, private)
	if err != nil {
		return "", "", "", err
	}
	issued, id, err := cloudflare.OriginCertificate(ctx, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE REQUEST", Bytes: request}), hostnames)
	if err != nil {
		return "", "", "", err
	}
	key = string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(private)}))
	// Re-encode so the stored bundle always splits back into its two blocks.
	if block, _ := pem.Decode(issued); block != nil {
		certificate = string(pem.EncodeToMemory(&pem.Block{Type: block.Type, Bytes: block.Bytes}))
	}
	if err := checkOrigin(certificate, key, hostnames, time.Now().AddDate(14, 0, 0)); err != nil {
		return "", "", "", fmt.Errorf("Origin CA certificate %s: %w", id, err)
	}
	return certificate, key, id, nil
}

check_cert.text:
// checkOrigin accepts a certificate for key that names every hostname and
// stays valid until then.
func checkOrigin(certificatePEM, keyPEM string, hostnames []string, until time.Time) error {
	keyBlock, _ := pem.Decode([]byte(keyPEM))
	if keyBlock == nil || keyBlock.Type != "RSA PRIVATE KEY" {
		return errors.New("bundle needs a PEM certificate and RSA private key")
	}
	certificate, err := checkOriginCertificate(certificatePEM, hostnames, until)
	if err != nil {
		return err
	}
	private, err := x509.ParsePKCS1PrivateKey(keyBlock.Bytes)
	if err != nil {
		return err
	}
	if !private.PublicKey.Equal(certificate.PublicKey) {
		return errors.New("certificate does not certify the key")
	}
	return nil
}

// checkOriginCertificate checks the PEM leaf without needing an OCI private
// key. Additional PEM chain certificates do not substitute for that leaf.
func checkOriginCertificate(certificatePEM string, hostnames []string, until time.Time) (*x509.Certificate, error) {
	block, _ := pem.Decode([]byte(certificatePEM))
	if block == nil || block.Type != "CERTIFICATE" {
		return nil, errors.New("origin needs a PEM certificate")
	}
	certificate, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, err
	}
	for _, name := range hostnames {
		if !slices.Contains(certificate.DNSNames, name) {
			return nil, fmt.Errorf("certificate does not name %s", name)
		}
	}
	if time.Now().Before(certificate.NotBefore) {
		return nil, fmt.Errorf("certificate is not valid before %s", certificate.NotBefore.Format(time.RFC3339))
	}
	if !until.Before(certificate.NotAfter) {
		return nil, fmt.Errorf("certificate expires %s", certificate.NotAfter.Format(time.DateOnly))
	}
	return certificate, nil
}

secret_paths.text:
// secret is the live Vault secret holding the origin bundle, or nil.
func (p Provisioner) secret(ctx context.Context, d Desired) (map[string]any, error) {
	rows, err := p.rows(ctx, "vault", "secret", "list", "--compartment-id", d.Control, "--vault-id", d.Vault, "--name", d.Names.Secret, "--all")
	if err != nil {
		return nil, err
	}
	var found map[string]any
	for _, r := range rows {
		if r["secret-name"] == d.Names.Secret && slices.Contains([]any{"CREATING", "ACTIVE", "UPDATING"}, r["lifecycle-state"]) {
			if found != nil {
				return nil, fmt.Errorf("more than one live vault secret is named %s", d.Names.Secret)
			}
			found = r
		}
	}
	return found, nil
}

// rotateSecret adds bundle as the secret's new current version.
func (p Provisioner) rotateSecret(ctx context.Context, d Desired, secret map[string]any, bundle string) error {
	id, err := command.ID(secret)
	if err != nil {
		return err
	}
	if _, err := p.Client.Call(ctx, "vault", "secret", "update-base64", "--secret-id", id,
		"--secret-content-content", base64.StdEncoding.EncodeToString([]byte(bundle))); err != nil {
		return err
	}
	_, err = p.await(ctx, d.Names.Secret, func() (map[string]any, error) { return p.secret(ctx, d) }, func(r map[string]any) bool {
		if r["lifecycle-state"] != "ACTIVE" {
			return false
		}
		current, _, err := p.originBundle(ctx, r, nil)
		return err == nil && sameCertificate(current, bundle)
	})
	return err
}

func (p Provisioner) storeSecret(ctx context.Context, d Desired, bundle string) error {
	_, err := p.Client.Call(ctx, "vault", "secret", "create-base64", "--compartment-id", d.Control, "--vault-id", d.Vault, "--key-id", d.Key,
		"--secret-name", d.Names.Secret, "--description", "Cloudflare Origin CA certificate and key of "+d.Names.LB,
		"--secret-content-content", base64.StdEncoding.EncodeToString([]byte(bundle)))
	if err != nil {
		return err
	}
	_, err = p.await(ctx, d.Names.Secret, func() (map[string]any, error) { return p.secret(ctx, d) },
		func(r map[string]any) bool { return r["lifecycle-state"] == "ACTIVE" })
	return err
}

// originBundle reads the origin certificate and key from their secret.
func (p Provisioner) originBundle(ctx context.Context, secret map[string]any, hostnames []string) (certificate, key string, err error) {
	if secret["lifecycle-state"] != "ACTIVE" {
		return "", "", fmt.Errorf("vault secret %v is %v, not ACTIVE", secret["secret-name"], secret["lifecycle-state"])
	}
	id, err := command.ID(secret)
	if err != nil {
		return "", "", err
	}
	bundle, err := p.data(ctx, "secrets", "secret-bundle", "get", "--secret-id", id)
	if err != nil {
		return "", "", err
	}
	content, _ := bundle["secret-bundle-content"].(map[string]any)
	wire, err := base64.StdEncoding.DecodeString(fmt.Sprint(content["content"]))
	if err != nil {
		return "", "", fmt.Errorf("vault secret %v content: %w", secret["secret-name"], err)
	}
	block, rest := pem.Decode(wire)
	if block == nil {
		return "", "", fmt.Errorf("vault secret %v holds no PEM bundle", secret["secret-name"])
	}
	certificate, key = string(pem.EncodeToMemory(block)), string(bytes.TrimSpace(rest))+"\n"
	return certificate, key, checkOrigin(certificate, key, hostnames, time.Now())
}

valid_ca.text:
// validCA accepts exactly one CA certificate in PEM.
func validCA(wire string) error {
	block, rest := pem.Decode([]byte(wire))
	if block == nil || block.Type != "CERTIFICATE" || len(bytes.TrimSpace(rest)) != 0 {
		return errors.New("member CA must be one PEM certificate")
	}
	certificate, err := x509.ParseCertificate(block.Bytes)
	if err != nil || !certificate.IsCA {
		return errors.New("member CA must be a CA certificate")
	}
	return nil
}

origin_pull_validate.text:
// OriginPull pins an operator-reviewed zone client certificate to its dedicated
// customer-owned root. The certificate and private key are uploaded separately.
type OriginPull struct {
	CACertificate string `json:"ca_certificate"`
	CertificateID string `json:"certificate_id"`
}

// Validate rejects missing configuration, unsafe IDs, and shared or unusable CAs.
func (o OriginPull) Validate() error {
	_, err := o.root()
	return err
}

func (o OriginPull) root() (*x509.Certificate, error) {
	if o.CertificateID == "" || strings.Trim(o.CertificateID, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-") != "" {
		return nil, errors.New("public_api.origin_pull.certificate_id must contain only letters, digits and hyphens and be nonempty")
	}
	if err := validCA(o.CACertificate); err != nil {
		return nil, fmt.Errorf("public_api.origin_pull.ca_certificate: %w", err)
	}
	block, _ := pem.Decode([]byte(o.CACertificate))
	root, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, err
	}
	sharedBlock, _ := pem.Decode([]byte(originPullCA))
	if sharedBlock == nil {
		return nil, errors.New("shared Cloudflare origin pull CA denylist is unavailable")
	}
	shared, err := x509.ParseCertificate(sharedBlock.Bytes)
	if err != nil {
		return nil, err
	}
	if bytes.Equal(root.RawSubjectPublicKeyInfo, shared.RawSubjectPublicKeyInfo) {
		return nil, errors.New("public_api.origin_pull.ca_certificate must not trust Cloudflare's shared origin pull CA")
	}
	now := time.Now()
	if !root.BasicConstraintsValid || root.KeyUsage&x509.KeyUsageCertSign == 0 ||
		!bytes.Equal(root.RawSubject, root.RawIssuer) || root.CheckSignatureFrom(root) != nil ||
		now.Before(root.NotBefore) || !now.Before(root.NotAfter) {
		return nil, errors.New("public_api.origin_pull.ca_certificate must be a currently valid self-signed signing CA")
	}
	return root, nil
}

origin_pull_state.text:
// originPullState checks the effective zone certificate and target hostname
// associations. Multiple active certificates do not identify the deployed one.
func (c Cloudflare) originPullState(ctx context.Context, zone string, names []string, o OriginPull, requireEnabled bool) (bool, error) {
	root, err := o.root()
	if err != nil {
		return false, err
	}
	path := "/zones/" + zone + "/origin_tls_client_auth"
	var certificates []originPullCertificate
	if err := c.do(ctx, http.MethodGet, path, nil, &certificates); err != nil {
		return false, err
	}
	if len(certificates) != 1 || certificates[0].ID != o.CertificateID || certificates[0].Status != "active" {
		return false, fmt.Errorf("zone origin pulls require exactly one certificate, reviewed ID %s with status active", o.CertificateID)
	}
	block, rest := pem.Decode([]byte(certificates[0].Certificate))
	if block == nil || block.Type != "CERTIFICATE" || len(bytes.TrimSpace(rest)) != 0 {
		return false, errors.New("zone origin pull client must be one PEM leaf certificate")
	}
	leaf, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return false, fmt.Errorf("zone origin pull client certificate: %w", err)
	}
	if leaf.IsCA || !slices.Contains(leaf.ExtKeyUsage, x509.ExtKeyUsageClientAuth) {
		return false, errors.New("zone origin pull client must be a non-CA leaf with explicit client auth usage")
	}
	if err := leaf.CheckSignatureFrom(root); err != nil {
		return false, fmt.Errorf("zone origin pull client is not directly signed by the reviewed CA: %w", err)
	}
	roots := x509.NewCertPool()
	roots.AddCert(root)
	if _, err := leaf.Verify(x509.VerifyOptions{Roots: roots, KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}}); err != nil {
		return false, fmt.Errorf("zone origin pull client certificate: %w", err)
	}
	for _, name := range names {
		var association struct {
			Hostname string         `json:"hostname"`
			Enabled  jsontext.Value `json:"enabled"`
		}
		// The supported GET is per hostname; collection /hostnames is PUT only.
		// Cloudflare stores no association without a certificate (PUT fails
		// with 1404), so 404 with code 1553 is the absent state and zone AOP
		// applies; verified live 2026-10-05. A successful explicit null also
		// voids it. Every other error fails closed.
		err := c.do(ctx, http.MethodGet, path+"/hostnames/"+url.PathEscape(name), nil, &association)
		var cf *cloudflareError
		if errors.As(err, &cf) && cf.Status == http.StatusNotFound && slices.Contains(cf.Codes, hostnameNotFound) {
			continue
		}
		if err != nil {
			return false, fmt.Errorf("cannot verify origin pull override for %s: %w", name, err)
		}
		if association.Hostname != name || string(association.Enabled) != "null" {
			return false, fmt.Errorf("origin pull hostname override for %s must be explicitly voided (enabled null) before publishing DNS", name)
		}
	}
	var settings struct {
		Enabled *bool `json:"enabled"`
	}
	if err := c.do(ctx, http.MethodGet, path+"/settings", nil, &settings); err != nil {
		return false, err
	}
	if settings.Enabled == nil || requireEnabled && !*settings.Enabled {
		return false, errors.New("custom zone origin pulls must read back enabled")
	}
	return *settings.Enabled, nil
}

check_balancer.text:
// field reads a nested member of a CLI-shaped OCI object.
func field(v any, path ...string) any {
	for _, key := range path {
		m, _ := v.(map[string]any)
		v = m[key]
	}
	return v
}

func same(v any, want any) bool { return fmt.Sprint(v) == fmt.Sprint(want) }

// CheckBalancer reports the first way a live, CLI-shaped load balancer
// differs from the configuration apply creates: bandwidth, hostname
// bindings, listeners and their client-certificate checks, and backend sets
// holding the planned backends: exactly every controller for ts-auth, and
// for terrabase and terrabase-primary exactly the seed, or, once the plan
// hands the sets to the controller, planned members only with at least one of
// them serving; and the routing policy sending Management to terrabase-primary.
func (d Desired) CheckBalancer(lb map[string]any) error {
	if err := d.OriginPull.Validate(); err != nil {
		return err
	}
	differs := func(what string, got any) error {
		return fmt.Errorf("load balancer %s %s differs from the plan: %v", d.Names.LB, what, got)
	}
	if lb["lifecycle-state"] != "ACTIVE" || lb["is-private"] != false || lb["shape-name"] != "flexible" ||
		!same(field(lb, "shape-details", "minimum-bandwidth-in-mbps"), d.MinMbps) || !same(field(lb, "shape-details", "maximum-bandwidth-in-mbps"), d.MaxMbps) {
		return differs("state or shape", []any{lb["lifecycle-state"], lb["is-private"], lb["shape-name"], lb["shape-details"]})
	}
	hostnames := map[string]string{}
	for _, h := range d.hosts() {
		hostnames[h.set] = h.name
	}
	live, _ := lb["hostnames"].(map[string]any)
	if !slices.Equal(slices.Sorted(maps.Keys(live)), slices.Sorted(maps.Keys(hostnames))) {
		return differs("hostnames", live)
	}
	for name, host := range hostnames {
		if field(live, name, "hostname") != host {
			return differs("hostname "+name, field(live, name, "hostname"))
		}
	}
	listeners, _ := lb["listeners"].(map[string]any)
	// Every HTTPS listener serves the first origin certificate or a rotation of it.
	served := servedCertificate(lb)
	if served != originCertificate && !strings.HasPrefix(served, originCertificate+"-") {
		return differs("origin certificate", served)
	}
	if !slices.Equal(slices.Sorted(maps.Keys(listeners)), slices.Sorted(slices.Values(append(slices.Collect(maps.Keys(hostnames)), "http")))) {
		return differs("listeners", slices.Sorted(maps.Keys(listeners)))
	}
	for name, v := range listeners {
		l, _ := v.(map[string]any)
		ok := l["protocol"] == "HTTP"
		if name == "http" {
			ok = ok && same(l["port"], 80) && l["ssl-configuration"] == nil && same(l["rule-set-names"], []string{"https-redirect"}) &&
				l["default-backend-set-name"] == "terrabase" && (l["hostname-names"] == nil || same(l["hostname-names"], []string{})) &&
				l["path-route-set-name"] == nil && l["routing-policy-name"] == nil
		} else {
			routes := map[string]any{"terrabase": managementRoutes}[name]
			ok = ok && same(l["port"], 443) && l["default-backend-set-name"] == name && same(l["hostname-names"], []string{name}) &&
				same(l["rule-set-names"], []string{"security-headers"}) && l["path-route-set-name"] == nil && l["routing-policy-name"] == routes &&
				field(l, "ssl-configuration", "certificate-name") == served && field(l, "ssl-configuration", "verify-peer-certificate") == true &&
				same(field(l, "connection-configuration", "idle-timeout"), IdleTimeout)
		}
		if !ok {
			return differs("listener "+name, l)
		}
	}
	redirect := field(lb, "rule-sets", "https-redirect", "items")
	items, _ := redirect.([]any)
	if len(items) != 1 {
		return differs("https-redirect rule set", redirect)
	}
	rule := items[0]
	conditions, _ := field(rule, "conditions").([]any)
	uri := field(rule, "redirect-uri")
	if field(rule, "action") != "REDIRECT" || !same(field(rule, "response-code"), 301) || len(conditions) != 1 ||
		field(conditions[0], "attribute-name") != "PATH" || field(conditions[0], "attribute-value") != "/" || field(conditions[0], "operator") != "PREFIX_MATCH" ||
		field(uri, "protocol") != "HTTPS" || field(uri, "host") != "{host}" || !same(field(uri, "port"), 443) ||
		field(uri, "path") != "{path}" || field(uri, "query") != "{query}" {
		return differs("https-redirect rule set", redirect)
	}
	policies, _ := lb["routing-policies"].(map[string]any)
	policy := policies[managementRoutes]
	if len(policies) != 1 || field(policy, "condition-language-version") != "V1" || !sameRules(field(policy, "rules"), managementRules) {
		return differs("routing policies", policies)
	}
	sets, _ := lb["backend-sets"].(map[string]any)
	if !slices.Equal(slices.Sorted(maps.Keys(sets)), slices.Sorted(slices.Values(append(slices.Collect(maps.Keys(hostnames)), primarySet)))) {
		return differs("backend sets", slices.Sorted(maps.Keys(sets)))
	}
	terrabaseWant := d.TerraBase
	if d.controllerOwned() {
		terrabaseWant = d.Members
	}
	wants := map[string][]Backend{"terrabase": terrabaseWant, primarySet: terrabaseWant, "ts-auth": d.Auth}
	if d.OrchHost != "" {
		wants["ts-orch"] = d.Orch
	}
	for name, want := range wants {
		var expected []string
		for _, b := range want {
			expected = append(expected, b.Addr.String())
		}
		slices.Sort(expected)
		set := sets[name]
		port := want[0].Addr.Port()
		rows, err := command.Rows(field(set, "backends"))
		live := liveBackends(lb, name)
		path := HealthPath
		if name == "ts-orch" {
			path = OrchHealthPath
		}
		ok := err == nil && field(set, "health-checker", "protocol") == "HTTP" &&
			field(set, "health-checker", "url-path") == path && same(field(set, "health-checker", "port"), port) &&
			same(field(set, "health-checker", "return-code"), 200)
		owned := (name == "terrabase" || name == primarySet) && d.controllerOwned()
		if owned {
			// The controller owns these backends: any planned members,
			// drained during a release, with at least one serving.
			serving := false
			for _, b := range rows {
				serving = serving || b["drain"] == nil || b["drain"] == false
			}
			ok = ok && serving && !slices.ContainsFunc(live, func(addr string) bool { return !slices.Contains(expected, addr) })
		} else {
			ok = ok && slices.Equal(live, expected)
		}
		for _, b := range rows {
			// Creation leaves these optional flags at their false defaults;
			// only the controller drains a TerraBase seat.
			for _, flag := range []string{"offline", "drain", "backup"} {
				ok = ok && (b[flag] == nil || b[flag] == false || flag == "drain" && owned)
			}
		}
		if bundle := map[string]string{"terrabase": memberCA, primarySet: memberCA, "ts-orch": cellCA}[name]; bundle != "" {
			forcePlaintext := field(set, "health-checker", "is-force-plain-text")
			ok = ok && (forcePlaintext == nil || forcePlaintext == false) &&
				field(set, "ssl-configuration", "certificate-name") == bundle && field(set, "ssl-configuration", "verify-peer-certificate") == true
		} else {
			ok = ok && field(set, "ssl-configuration") == nil
		}
		if !ok {
			return differs("backend set "+name, set)
		}
	}
	bundles := []string{served, memberCA}
	if d.OrchHost != "" {
		bundles = append(bundles, cellCA)
	}
	for _, name := range bundles {
		if field(lb, "certificates", name) == nil {
			return differs("certificate "+name, "missing")
		}
	}
	if !sameCA(lb, served, d.OriginPull.CACertificate) {
		return differs("origin-pull CA", "missing or different from the reviewed customer CA")
	}
	publicCertificate, _ := field(lb, "certificates", served, "public-certificate").(string)
	if _, err := checkOriginCertificate(publicCertificate, d.hostNames(), time.Now()); err != nil {
		return fmt.Errorf("load balancer %s origin certificate: %w", d.Names.LB, err)
	}
	return nil
}

check_rules_ca.text:
// sameRules reports whether CLI-shaped routing rules are exactly want.
func sameRules(live any, want []any) bool {
	rules, _ := live.([]any)
	if len(rules) != len(want) {
		return false
	}
	for i, rule := range rules {
		w := want[i].(map[string]any)
		actions, _ := field(rule, "actions").([]any)
		wantActions := w["actions"].([]any)
		if field(rule, "name") != w["name"] || field(rule, "condition") != w["condition"] || len(actions) != len(wantActions) {
			return false
		}
		for j, action := range actions {
			wa := wantActions[j].(map[string]any)
			if field(action, "name") != wa["name"] || field(action, "backend-set-name") != wa["backendSetName"] {
				return false
			}
		}
	}
	return true
}

// sameCA reports whether a load balancer bundle holds exactly pemCA.
func sameCA(lb map[string]any, name, pemCA string) bool {
	live, _ := field(lb, "certificates", name, "ca-certificate").(string)
	if validCA(live) != nil || validCA(pemCA) != nil {
		return false
	}
	a, _ := pem.Decode([]byte(live))
	b, _ := pem.Decode([]byte(pemCA))
	return a != nil && b != nil && bytes.Equal(a.Bytes, b.Bytes)
}

// CheckOriginRules reports whether NSG ingress rows admit exactly TCP 80 and
// 443 from each of Cloudflare's ranges, and nothing else.
func CheckOriginRules(rows []map[string]any, ranges []string) error {
	want := OriginRules(ranges)
	var have []Rule
	for _, row := range rows {
		r, ok := listed(row)
		if !ok || !slices.Contains(want, r) || slices.Contains(have, r) {
			return fmt.Errorf("load balancer NSG rule %v admits more than Cloudflare's ranges on 80 and 443", row["id"])
		}
		have = append(have, r)
	}
	if len(have) != len(want) {
		return fmt.Errorf("load balancer NSG admits %d of Cloudflare's %d range and port pairs; run public-api origin-ips --apply", len(have), len(want))
	}
	return nil
}

cloudflare_http.text:
const (
	// Zone is the Cloudflare zone of every public name.
	Zone = "terrascale.tech"
	// TokenEnv names the Cloudflare API token, OCI Vault secret
	// gru-1-cloudflare-dns-edit-token (docs/secrets.md).
	TokenEnv      = "CF_API_TOKEN"
	cloudflareAPI = "https://api.cloudflare.com/client/v4"
	// originValidityDays is the longest Origin CA validity, 15 years.
	originValidityDays = 5475
)

// Cloudflare is the Cloudflare API client. Token may be empty for the
// published IP ranges, which need no authentication.
type Cloudflare struct {
	BaseURL string
	Token   string
	HTTP    *http.Client
}

// cloudflareError is an unsuccessful Cloudflare response.
type cloudflareError struct {
	Status int
	Detail string
	Codes  []int
}

func (e *cloudflareError) Error() string { return fmt.Sprintf("HTTP %d: %s", e.Status, e.Detail) }

func (c Cloudflare) do(ctx context.Context, method, path string, body, result any) error {
	var payload io.Reader
	if body != nil {
		wire, err := json.Marshal(body)
		if err != nil {
			return err
		}
		payload = bytes.NewReader(wire)
	}
	request, err := http.NewRequestWithContext(ctx, method, c.BaseURL+path, payload)
	if err != nil {
		return err
	}
	if c.Token != "" {
		request.Header.Set("Authorization", "Bearer "+c.Token)
	}
	request.Header.Set("Content-Type", "application/json")
	client := c.HTTP
	if client == nil {
		client = &http.Client{Timeout: 30 * time.Second}
	}
	response, err := client.Do(request)
	if err != nil {
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, err)
	}
	defer response.Body.Close()
	var envelope struct {
		Success bool           `json:"success"`
		Errors  []any          `json:"errors"`
		Result  jsontext.Value `json:"result"`
	}
	if err := json.UnmarshalRead(io.LimitReader(response.Body, 1<<20), &envelope); err != nil {
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, &cloudflareError{Status: response.StatusCode, Detail: err.Error()})
	}
	if !envelope.Success || response.StatusCode/100 != 2 {
		var codes []int
		for _, e := range envelope.Errors {
			if code, ok := field(e, "code").(float64); ok {
				codes = append(codes, int(code))
			}
		}
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, &cloudflareError{response.StatusCode, fmt.Sprint(envelope.Errors), codes})
	}
	if result == nil {
		return nil
	}
	return json.Unmarshal(envelope.Result, result)
}

// OriginIPs returns Cloudflare's published IPv4 ranges, the only sources the
// load balancer admits.
func (c Cloudflare) OriginIPs(ctx context.Context) ([]string, error) {
	var ips struct {
		IPv4 []string `json:"ipv4_cidrs"`
	}
	if err := c.do(ctx, http.MethodGet, "/ips", nil, &ips); err != nil {
		return nil, err
	}
	if len(ips.IPv4) == 0 || len(ips.IPv4) > 50 {
		return nil, fmt.Errorf("Cloudflare publishes %d IPv4 ranges, want 1 to 50", len(ips.IPv4))
	}
	for i, cidr := range ips.IPv4 {
		prefix, err := netip.ParsePrefix(cidr)
		if err != nil || !prefix.Addr().Is4() || prefix != prefix.Masked() || prefix.Bits() < 8 || !prefix.Addr().IsGlobalUnicast() || prefix.Addr().IsPrivate() {
			return nil, fmt.Errorf("Cloudflare publishes an unusable IPv4 range %q", cidr)
		}
		ips.IPv4[i] = prefix.String()
	}
	slices.Sort(ips.IPv4)
	return slices.Compact(ips.IPv4), nil
}

func (c Cloudflare) zoneID(ctx context.Context) (string, error) {
	var zones []struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	}
	if err := c.do(ctx, http.MethodGet, "/zones?name="+url.QueryEscape(Zone), nil, &zones); err != nil {
		return "", err
	}
	if len(zones) != 1 || zones[0].Name != Zone || zones[0].ID == "" {
		return "", fmt.Errorf("Cloudflare token sees %d zones named %s, want 1", len(zones), Zone)
	}
	return zones[0].ID, nil
}

strict_tls.text:
// record is a Cloudflare DNS record.
type record struct {
	ID      string `json:"id,omitempty"`
	Type    string `json:"type"`
	Name    string `json:"name"`
	Content string `json:"content"`
	Proxied bool   `json:"proxied"`
	TTL     int    `json:"ttl"`
}

// configRule pins SSL Full (strict) for the public names only, leaving the
// zone's other hostnames on their current mode.
type configRule struct {
	ID          string         `json:"id,omitempty"`
	Ref         string         `json:"ref"`
	Description string         `json:"description"`
	Expression  string         `json:"expression"`
	Action      string         `json:"action"`
	Parameters  map[string]any `json:"action_parameters"`
	Enabled     bool           `json:"enabled"`
}

func (r configRule) same(other configRule) bool {
	return r.Expression == other.Expression && r.Action == other.Action && r.Enabled == other.Enabled &&
		len(other.Parameters) == 1 && other.Parameters["ssl"] == "strict"
}

// strictTail reports whether only rules that set nothing but Full (strict),
// such as another cell's, follow rules[i]: a later rule wins, and these
// cannot downgrade it.
func strictTail(rules []configRule, i int) bool {
	for _, r := range rules[i+1:] {
		if r.Action != "set_config" || len(r.Parameters) != 1 || r.Parameters["ssl"] != "strict" {
			return false
		}
	}
	return true
}

// checkStrictTLS verifies the last matching configuration cannot downgrade TLS.
func (c Cloudflare) checkStrictTLS(ctx context.Context, entry string, want configRule) error {
	var ruleset struct {
		Rules []configRule `json:"rules"`
	}
	if err := c.do(ctx, http.MethodGet, entry, nil, &ruleset); err != nil {
		return err
	}
	count := 0
	for _, r := range ruleset.Rules {
		if r.Ref == want.Ref {
			count++
		}
	}
	i := slices.IndexFunc(ruleset.Rules, func(r configRule) bool { return r.Ref == want.Ref })
	if count != 1 || !want.same(ruleset.Rules[i]) || !strictTail(ruleset.Rules, i) {
		return fmt.Errorf("Cloudflare rule %s must be uniquely enabled with SSL Full (strict) at the end of the configuration ruleset", want.Ref)
	}
	return nil

edge_steps.text:
// edgeSteps plans the Cloudflare side of the edge: Full (strict) to the
// origin, Authenticated Origin Pulls, then proxied A records to address.
//
// Settings come first so no proxied request reaches the origin without its
// client certificate. A name holding any other record is refused.
func (c Cloudflare) edgeSteps(ctx context.Context, names []string, address netip.Addr, cell string, originPull OriginPull) ([]step, error) {
	if !address.Is4() || !address.IsGlobalUnicast() || address.IsPrivate() {
		return nil, fmt.Errorf("%s is not a public IPv4 address", address)
	}
	if err := originPull.Validate(); err != nil {
		return nil, err
	}
	zone, err := c.zoneID(ctx)
	if err != nil {
		return nil, err
	}
	var steps []step
	quoted := make([]string, len(names))
	for i, name := range names {
		if !strings.HasSuffix(name, "."+Zone) {
			return nil, fmt.Errorf("%s is outside zone %s", name, Zone)
		}
		quoted[i] = `"` + name + `"`
	}
	aopEnabled, err := c.originPullState(ctx, zone, names, originPull, false)
	if err != nil {
		return nil, err
	}
	strict := configRule{Ref: "ts-orch-" + cell + "-api-ssl-strict", Description: cell + " public API: Full (strict) to the origin",
		Expression: "(http.host in {" + strings.Join(quoted, " ") + "})", Action: "set_config",
		Parameters: map[string]any{"ssl": "strict"}, Enabled: true}
	entry := "/zones/" + zone + "/rulesets/phases/http_config_settings/entrypoint"
	var ruleset struct {
		ID    string       `json:"id"`
		Rules []configRule `json:"rules"`
	}
	err = c.do(ctx, http.MethodGet, entry, nil, &ruleset)
	if cf, ok := errors.AsType[*cloudflareError](err); ok && cf.Status == http.StatusNotFound {
		err, ruleset.ID = nil, ""
	}
	if err != nil {
		return nil, err
	}
	what := fmt.Sprintf("set SSL Full (strict) for %s (configuration rule %s)", strings.Join(names, ", "), strict.Ref)
	current := slices.IndexFunc(ruleset.Rules, func(r configRule) bool { return r.Ref == strict.Ref })
	for i, r := range ruleset.Rules {
		if r.Ref == strict.Ref && i != current {
			return nil, fmt.Errorf("Cloudflare configuration rule %s is duplicated; resolve it by hand", strict.Ref)
		}
	}
	writeStrict := func(ctx context.Context, method, path string, body any) error {
		if err := c.do(ctx, method, path, body, nil); err != nil {
			return err
		}
		return c.checkStrictTLS(ctx, entry, strict)
	}
	switch {
	case ruleset.ID == "":
		steps = append(steps, step{what, func(ctx context.Context) error {
			return writeStrict(ctx, http.MethodPut, entry, map[string]any{"rules": []configRule{strict}})
		}})
	case current < 0:
		steps = append(steps, step{what, func(ctx context.Context) error {
			return writeStrict(ctx, http.MethodPost, "/zones/"+zone+"/rulesets/"+ruleset.ID+"/rules", strict)
		}})
	case !strict.same(ruleset.Rules[current]) || !strictTail(ruleset.Rules, current):
		id := ruleset.Rules[current].ID
		steps = append(steps, step{what, func(ctx context.Context) error {
			// Cloudflare's documented empty after position moves the rule last.
			body := struct {
				configRule
				Position map[string]string `json:"position"`
			}{strict, map[string]string{"after": ""}}
			return writeStrict(ctx, http.MethodPatch, "/zones/"+zone+"/rulesets/"+ruleset.ID+"/rules/"+id, body)
		}})
	}
	if !aopEnabled {
		steps = append(steps, step{"enable custom zone Authenticated Origin Pulls", func(ctx context.Context) error {
			if err := c.do(ctx, http.MethodPut, "/zones/"+zone+"/origin_tls_client_auth/settings", map[string]bool{"enabled": true}, nil); err != nil {
				return err
			}
			_, err := c.originPullState(ctx, zone, names, originPull, true)
			return err
		}})
	}
	for _, name := range names {
		var records []record
		if err := c.do(ctx, http.MethodGet, "/zones/"+zone+"/dns_records?name="+url.QueryEscape(name), nil, &records); err != nil {
			return nil, err
		}
		want := record{Type: "A", Name: name, Content: address.String(), Proxied: true, TTL: 1}
		method, path, what := http.MethodPost, "/zones/"+zone+"/dns_records", fmt.Sprintf("create A %s %s (proxied)", name, want.Content)
		switch {
		case len(records) == 0:
		case len(records) == 1 && records[0].Type == "A" && records[0].Name == name:
			if records[0].Content == want.Content && records[0].Proxied {
				continue
			}
			method, path = http.MethodPut, path+"/"+records[0].ID
			what = fmt.Sprintf("update A %s %s (proxied %t) -> %s (proxied)", name, records[0].Content, records[0].Proxied, want.Content)
		default:
			return nil, fmt.Errorf("%s already holds %d records; resolve them by hand", name, len(records))
		}
		steps = append(steps, step{what, func(ctx context.Context) error {
			if _, err := c.originPullState(ctx, zone, names, originPull, true); err != nil {
				return err
			}
			if err := c.checkStrictTLS(ctx, entry, strict); err != nil {
				return err
			}
			return c.do(ctx, method, path, want, nil)
		}})
	}
	return steps, nil
}

