retry_identity.text:
// Retry identity binds the durable operation to the provider target and
// canonical mutation payload, including requests retried after process loss.
func retryToken(ctx context.Context, client *SDKClient, command sdkcli.Command) (*string, error) {
	step, err := canonicalRequest(client.Region, command)
	if err != nil {
		return nil, err
	}
	return new(ociresource.RetryToken(ctx, string(step))), nil
}

// CreateRetryIdentity shares the SDK's exact request identity with the durable
// foundation journal. An empty token means OCI cannot deduplicate a replay.
func CreateRetryIdentity(ctx context.Context, region string, args ...string) (digest, token string, err error) {
	command, err := sdkcli.Parse(args)
	if err != nil {
		return "", "", err
	}
	if _, ok := creators[command.Path]; !ok || !strings.HasSuffix(command.Path, " create") {
		return "", "", errors.New("OCI command is not a supported foundation create")
	}
	step, err := canonicalRequest(region, command)
	if err != nil {
		return "", "", err
	}
	sum := sha256.Sum256(step)
	if command.Path != "os bucket create" && command.Path != "os retention-rule create" {
		token = ociresource.RetryToken(ctx, string(step))
	}
	return hex.EncodeToString(sum[:]), token, nil
}

func canonicalRequest(region string, command sdkcli.Command) ([]byte, error) {
	flags := make(map[string]any, len(command.Flags))
	for key, value := range command.Flags {
		if key == "wait-for-state" {
			continue
		}
		flags[key] = value
		if strings.HasPrefix(value, "{") || strings.HasPrefix(value, "[") {
			payload := jsontext.Value(value)
			if err := payload.Format(jsontext.ReorderRawObjects(true)); err != nil {
				return nil, fmt.Errorf("invalid OCI %s payload", key)
			}
			flags[key] = payload
		}
	}
	step, err := json.Marshal(map[string]any{"region": region, "path": command.Path, "flags": flags}, json.Deterministic(true))
	if err != nil {
		return nil, errors.New("OCI retry identity is invalid")
	}
	return step, nil
}

sdkcli_parse.text:
// Command is a parsed CLI invocation: its word path and its flags.
type Command struct {
	Path  string
	Flags map[string]string
	All   bool
	// used records the flags a handler read, so a flag no handler serves
	// (for example a list filter) is never silently dropped.
	used map[string]bool
}

// Parse splits CLI arguments into the command path and its flags.
func Parse(args []string) (Command, error) {
	command := Command{Flags: map[string]string{}, used: map[string]bool{}}
	var path []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "--") {
			if len(command.Flags) > 0 || command.All {
				return Command{}, fmt.Errorf("positional OCI argument %q follows a flag", arg)
			}
			path = append(path, arg)
			continue
		}
		name := strings.TrimPrefix(arg, "--")
		if name == "all" {
			command.All = true
			continue
		}
		if i+1 >= len(args) || strings.HasPrefix(args[i+1], "--") {
			return Command{}, fmt.Errorf("OCI flag --%s has no value", name)
		}
		if _, repeated := command.Flags[name]; repeated {
			return Command{}, fmt.Errorf("OCI flag --%s is repeated", name)
		}
		command.Flags[name] = args[i+1]
		i++
	}
	command.Path = strings.Join(path, " ")
	return command, nil
}

// value returns a flag's value, or "", and records that it was read.
func (c Command) value(name string) string {
	if c.used != nil {
		c.used[name] = true
	}
	return c.Flags[name]
}

// unused lists the flags no handler read, in sorted order.
func (c Command) unused() []string {
	var names []string
	for name := range c.Flags {
		if !c.used[name] {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	return names
}

func (c Command) flag(name string) (string, error) {
	value := c.value(name)
	if value == "" {
		return "", fmt.Errorf("OCI %s requires --%s", c.Path, name)
	}
	return value, nil
}

// optional returns a pointer to a present flag value, or nil.
func (c Command) optional(name string) *string {
	if value := c.value(name); value != "" {
		return &value
	}
	return nil
}

// Client serves commands for one region through the shared rate-limited factory.
type Client struct {
	factory *ociclient.Factory
	// endpoint overrides every service host; tests point it at a fake.
	endpoint string
}

// NewClient shares the authenticated provider, rate limits and retry policy of factory.
func NewClient(factory *ociclient.Factory, endpoint string) *Client {
	return &Client{factory: factory, endpoint: endpoint}
}

// Factory is the shared rate-limited factory this client reads through.
func (c *Client) Factory() *ociclient.Factory { return c.factory }

func (c *Client) pin(client *common.BaseClient) {
	client.HTTPClient = strictResponses{next: client.HTTPClient}
	ociclient.ConfigureRequestCancellation(client)
	if c.endpoint != "" {
		client.Host = c.endpoint
	}
}

sdkcli_read_render.text:
// Strict decoding keeps ambiguous or truncated provider documents out of inventory.
type strictResponses struct{ next common.HTTPRequestDispatcher }

func (d strictResponses) Do(request *http.Request) (*http.Response, error) {
	response, err := d.next.Do(request)
	if err != nil || response == nil || request.Method == http.MethodHead || response.StatusCode < 200 || response.StatusCode >= 300 {
		return response, err
	}
	const limit = 32 << 20
	wire, err := io.ReadAll(io.LimitReader(response.Body, limit+1))
	response.Body.Close()
	if err != nil {
		return nil, fmt.Errorf("read OCI response: %w", err)
	}
	if len(wire) > limit {
		return nil, errors.New("OCI response exceeds 32 MiB")
	}
	var value any
	if err := json.Unmarshal(wire, &value); err != nil {
		return nil, fmt.Errorf("invalid OCI response: %w", err)
	}
	response.Body = io.NopCloser(bytes.NewReader(wire))
	return response, nil
}

var (
	clientsMu sync.Mutex
	clients   = map[string]*Client{}
)

// ForRegion returns the shared client for region. An empty region selects
// the bootstrap region, which serves the tenancy-global IAM reads the CLI
// sent to the profile's default region.
func ForRegion(region string) (*Client, error) {
	if region == "" {
		region = catalog.OCIRegion(catalog.Bootstrap)
	}
	clientsMu.Lock()
	defer clientsMu.Unlock()
	if client := clients[region]; client != nil {
		return client, nil
	}
	factory, err := ociclient.OperatorConfig(region)
	if err != nil {
		return nil, err
	}
	client := NewClient(factory, "")
	clients[region] = client
	return client, nil
}

// Call serves one CLI command and returns the CLI "data" document as JSON.
// handled is false, with ErrUnsupported, when the command is not served.
func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

// Render marshals an SDK value and rewrites member names to the CLI's
// kebab-case. Members of user-keyed maps keep their keys.
func Render(value any) (jsontext.Value, error) {
	wire, err := json.Marshal(value, json.FormatNilSliceAsNull(true))
	if err != nil {
		return nil, fmt.Errorf("encode OCI response: %w", err)
	}
	return kebab(jsontext.Value(wire), false)
}

// userKeyed are SDK members whose object keys are user data, not schema.
var userKeyed = map[string]bool{
	"freeformTags": true, "definedTags": true, "systemTags": true, "metadata": true, "extendedMetadata": true,
	"securityAttributes": true, "schemaData": true, "opcMeta": true, "lockedAttributes": true,
}

// nameKeyed are SDK members keyed by user-defined resource names (an NLB's
// backend sets and listeners, a load balancer's named sets) whose values are
// still schema objects: only the immediate keys are preserved, so a listener's
// default-backend-set-name keeps resolving to its backend set.
var nameKeyed = map[string]bool{
	"backendSets": true, "listeners": true, "certificates": true, "hostnames": true,
	"pathRouteSets": true, "ruleSets": true, "routingPolicies": true, "sslCipherSuites": true,
}

func kebab(value jsontext.Value, preserveKeys bool) (jsontext.Value, error) {
	switch value.Kind() {
	case '{':
		var typed map[string]jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make(map[string]jsontext.Value, len(typed))
		for key, member := range typed {
			name := key
			if !preserveKeys {
				name = Kebab(key)
			}
			if member.Kind() == '{' && !preserveKeys && nameKeyed[key] {
				var named map[string]jsontext.Value
				if err := json.Unmarshal(member, &named); err != nil {
					return nil, err
				}
				entries := make(map[string]jsontext.Value, len(named))
				for entryName, entry := range named {
					converted, err := kebab(entry, false)
					if err != nil {
						return nil, err
					}
					entries[entryName] = converted
				}
				encoded, err := json.Marshal(entries, json.Deterministic(true))
				if err != nil {
					return nil, err
				}
				result[name] = encoded
				continue
			}
			// The members of a user-keyed map are user data at any depth
			// (defined tags nest one level), so preserve keys below it.
			converted, err := kebab(member, preserveKeys || userKeyed[key])
			if err != nil {
				return nil, err
			}
			result[name] = converted
		}
		wire, err := json.Marshal(result, json.Deterministic(true))
		return jsontext.Value(wire), err
	case '[':
		var typed []jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make([]jsontext.Value, len(typed))
		for index, member := range typed {
			converted, err := kebab(member, preserveKeys)
			if err != nil {
				return nil, err
			}
			result[index] = converted
		}
		wire, err := json.Marshal(result)
		return jsontext.Value(wire), err
	default:
		return value, nil
	}

sdkcli_pages.text:
// pages collects every page of a list call, bounded so a misbehaving
// endpoint cannot loop.
func pages[T any](all bool, fetch func(page *string) ([]T, *string, error)) ([]T, error) {
	var items []T
	var page *string
	for range 256 {
		batch, next, err := fetch(page)
		if err != nil {
			return nil, err
		}
		items = append(items, batch...)
		if !all || next == nil || *next == "" {
			if items == nil {
				items = []T{}
			}
			return items, nil
		}
		page = next
	}
	return nil, errors.New("OCI list exceeds its page bound")
}

